<script setup>
import {computed,ref,watch} from 'vue';import {useAuthStore} from '../../store/auth.js';import api from '../../services/api';
const props=defineProps({agencyId:{type:Number,required:true},noteId:Number,saveDraft:Function});const emit=defineEmits(['saved']);const auth=useAuthStore();
const allowed=computed(()=>['super_admin','superadmin'].includes(auth.user?.role));
const disposition=ref('chart_only'),reason=ref(''),confirmed=ref(false),busy=ref(false),error=ref(''),notice=ref(''),savedDraftId=ref(null);
let generation=0;
watch(()=>[props.agencyId,props.noteId],()=>{generation++;savedDraftId.value=null;reason.value='';confirmed.value=false;error.value='';notice.value='';busy.value=false;});
async function save(){if(!allowed.value||busy.value||!confirmed.value||reason.value.trim().length<10)return;const requestGeneration=generation,agencyId=props.agencyId,existingNoteId=props.noteId;busy.value=true;error.value='';notice.value='';try{
 const noteId=existingNoteId||savedDraftId.value||await props.saveDraft?.();if(requestGeneration!==generation)return;if(!noteId)throw new Error('Save the current note content before recording its chart disposition.');savedDraftId.value=Number(noteId);
 const {data}=await api.post(`/medical-billing/notes/${noteId}/billing-disposition`,{agencyId,disposition:disposition.value,reason:reason.value.trim(),confirmed:true},{skipGlobalLoading:true});if(requestGeneration!==generation)return;notice.value=data.message;emit('saved',data);
 }catch(e){if(requestGeneration!==generation)return;error.value=e.response?.data?.error?.message||e.message||'The chart disposition could not be recorded. Any saved draft remains unsigned.';}finally{if(requestGeneration===generation)busy.value=false;}}
</script>
<template><details v-if="allowed" class="chart-disposition"><summary>Save in chart without a claim · Superadmin</summary><p>This records an administrative annotation and excludes this encounter from billing. Signed clinical text stays intact. Existing transmissions remain on record for follow-up.</p><form @submit.prevent="save"><label>Chart disposition<select v-model="disposition" :disabled="busy"><option value="chart_only">Save in chart only</option><option value="entered_in_error">Mark as entered in error</option><option value="documented_elsewhere">Documented elsewhere</option><option value="therapy_notes">Note is in Therapy Notes EHR</option></select></label><label>Reason / external documentation reference<textarea v-model="reason" required minlength="10" maxlength="2000" :disabled="busy" /></label><label><input v-model="confirmed" type="checkbox" :disabled="busy" /> I confirm this encounter must not generate or submit a claim.</label><button :disabled="busy||!confirmed||reason.trim().length<10">{{ busy?'Saving…':'Save in chart · No claim' }}</button></form><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p></details></template>
<style scoped>.chart-disposition{padding:14px;border:1px solid #c8d1dd;border-radius:8px;margin:14px 0}summary{cursor:pointer;font-weight:600}label{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:12px 0}textarea{width:100%;min-height:70px}button,input,select,textarea{font:inherit;padding:8px;border:1px solid #bccad9;border-radius:6px}p{font-size:13px;line-height:1.5}[role=alert]{color:#a12525}</style>
